INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1015, '数学', '三年级', '拓展', 3, '{"stem": "在○里填“>”“<”或“=”：12×3 ○ 13×2；52×1 ○ 51×2；91×5 ○ 95×1；44×2 ○ 42×4。你发现了什么？", "options": null}', '12×3>13×2；52×1<51×2；91×5>95×1；44×2<42×4。发现：交换两个因数的位置积会变，不能只看数字大小，要先算出积再比较；当两个因数的数字差不多时，一个因数略大几、另一个略小几，积的大小取决于「几」的差距方向，不能直接判断。', '逐项计算：12×3=36，13×2=26，36>26；52×1=52，51×2=102，52<102；91×5=455，95×1=95，455>95；44×2=88，42×4=168，88<168。规律：因数位置互换积一般不同，比较时必须先算再比。', 'paper', '["practice", "VG-G3-2-2", "ykl3sx", "2.2"]', NULL, 0);
